insert into public.testimonials (name,location,rating,quote,status,created_at) select 'Tunde Ajayi','Ikeja, Lagos',5,'Bought the His & Hers combo for our anniversary. My wife has not stopped wearing hers. Customer service on WhatsApp was instant.','approved','2026-07-15T11:22:00.000Z' where not exists (select 1 from public.testimonials where quote = 'Bought the His & Hers combo for our anniversary. My wife has not stopped wearing hers. Customer service on WhatsApp was instant.');
